import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.security.*;
import java.security.spec.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.concurrent.locks.ReentrantLock;

/**
 * FileProcessingService - processes uploaded files from reverse proxy
 * Handles graceful shutdown via shutdown hook for container orchestration
 */
public class FileProcessingService {

    private static final String UPLOAD_DIR = "/var/spool/fileproc/incoming";
    private static final String PROCESSED_DIR = "/var/spool/fileproc/done";
    private static final String QUARANTINE_DIR = "/var/spool/fileproc/quarantine";

    private static final int GCM_TAG_BITS = 128;
    private static final int GCM_NONCE_BYTES = 12;

    private final ExecutorService workerPool;
    private final AtomicInteger activeJobs = new AtomicInteger(0);
    private final ConcurrentHashMap<String, FileTask> taskRegistry = new ConcurrentHashMap<>();

    // Strong, randomly generated key for AES-GCM content protection
    private final SecretKey aesKey;
    private final SecureRandom secureRandom = new SecureRandom();

    // Thread-safe shutdown coordination
    private volatile boolean shuttingDown = false;
    private volatile boolean drainComplete = false;
    private final ReentrantLock processingLock = new ReentrantLock();
    private final AtomicReference<ProcessingState> currentState = new AtomicReference<>(null);

    private static class ProcessingState {
        final String taskId;
        final File file;
        ProcessingState(String taskId, File file) {
            this.taskId = taskId;
            this.file = file;
        }
    }

    public FileProcessingService(int poolSize) throws Exception {
        this.workerPool = Executors.newFixedThreadPool(poolSize);
        KeyGenerator kg = KeyGenerator.getInstance("AES");
        kg.init(256);
        this.aesKey = kg.generateKey();
        registerShutdownHandlers();
    }

    private void registerShutdownHandlers() {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            System.out.println("[SHUTDOWN] Initiating graceful shutdown");
            shuttingDown = true;

            // Acquire lock to ensure we don't race with worker threads
            processingLock.lock();
            try {
                ProcessingState state = currentState.get();
                if (state != null && state.file != null && state.file.exists()) {
                    // Move current file back to incoming for reprocessing after restart
                    Path source = state.file.toPath();
                    Path dest = Paths.get(UPLOAD_DIR, state.file.getName());
                    try {
                        Files.move(source, dest, StandardCopyOption.ATOMIC_MOVE);
                        System.out.println("[SHUTDOWN] Rescued file: " + state.file.getName());
                    } catch (IOException e) {
                        System.err.println("[SHUTDOWN] Failed to rescue file: " + e.getMessage());
                    }
                    // Remove from task registry so it gets re-queued
                    taskRegistry.remove(state.taskId);
                    currentState.set(null);
                }
            } finally {
                processingLock.unlock();
            }

            // Wait for active jobs to complete
            workerPool.shutdown();
            try {
                if (!workerPool.awaitTermination(3, TimeUnit.SECONDS)) {
                    workerPool.shutdownNow();
                }
            } catch (InterruptedException e) {
                workerPool.shutdownNow();
            }
            drainComplete = true;
        }, "shutdown-hook"));
    }

    /**
     * Resolve a child path under a trusted base directory, rejecting any path
     * that escapes the base directory (path traversal protection).
     */
    private static Path resolveSafe(String baseDir, String childName) throws IOException {
        Path base = Paths.get(baseDir).toAbsolutePath().normalize();
        // Use only the final path element of the provided name to prevent traversal
        Path childOnly = Paths.get(childName).getFileName();
        if (childOnly == null) {
            throw new IOException("Invalid file name: " + childName);
        }
        Path resolved = base.resolve(childOnly).normalize();
        if (!resolved.startsWith(base)) {
            throw new IOException("Path traversal attempt detected: " + childName);
        }
        return resolved;
    }

    public void processFile(String taskId, File inputFile) throws Exception {
        if (shuttingDown) {
            throw new IllegalStateException("Service is shutting down");
        }

        // Validate that the input file actually lives inside the upload directory
        Path safeInput = resolveSafe(UPLOAD_DIR, inputFile.getName());
        if (!safeInput.equals(inputFile.toPath().toAbsolutePath().normalize())) {
            // Ensure we only operate on files inside UPLOAD_DIR
            inputFile = safeInput.toFile();
        }

        activeJobs.incrementAndGet();
        try {
            // Register task
            FileTask task = new FileTask(taskId, inputFile, System.currentTimeMillis());
            taskRegistry.put(taskId, task);

            // Atomically set both taskId and file together under lock
            processingLock.lock();
            try {
                validateFileIntegrity(inputFile);
                currentState.set(new ProcessingState(taskId, inputFile));
            } finally {
                processingLock.unlock();
            }

            // Perform actual processing
            byte[] content = Files.readAllBytes(inputFile.toPath());
            byte[] processed = transformContent(content);

            // Write to processed directory (path-traversal-safe)
            Path outputPath = resolveSafe(PROCESSED_DIR, inputFile.getName() + ".processed");
            Files.write(outputPath, processed, StandardOpenOption.CREATE_NEW);

            // Move original to done (path-traversal-safe)
            Path donePath = resolveSafe(PROCESSED_DIR, inputFile.getName());
            Files.move(inputFile.toPath(), donePath, StandardCopyOption.ATOMIC_MOVE);

            task.markComplete();

            processingLock.lock();
            try {
                currentState.set(null);
            } finally {
                processingLock.unlock();
            }

        } finally {
            activeJobs.decrementAndGet();
        }
    }

    private void validateFileIntegrity(File file) throws Exception {
        // Compute SHA-256 to verify upload integrity (proxy sets X-Content-SHA256)
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream is = new BufferedInputStream(new FileInputStream(file))) {
            byte[] buffer = new byte[8192];
            int read;
            while ((read = is.read(buffer)) != -1) {
                digest.update(buffer, 0, read);
            }
        }
        // In production, compare with header value from proxy
        byte[] hash = digest.digest();
        if (hash.length == 0) {
            throw new SecurityException("Integrity check failed");
        }
    }

    private byte[] transformContent(byte[] input) throws Exception {
        // Apply authenticated encryption (AES-256-GCM) for storage.
        byte[] nonce = new byte[GCM_NONCE_BYTES];
        secureRandom.nextBytes(nonce);

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_BITS, nonce);
        cipher.init(Cipher.ENCRYPT_MODE, aesKey, spec);
        byte[] ciphertext = cipher.doFinal(input);

        // Prepend nonce so it can be recovered for decryption.
        byte[] output = new byte[nonce.length + ciphertext.length];
        System.arraycopy(nonce, 0, output, 0, nonce.length);
        System.arraycopy(ciphertext, 0, output, nonce.length, ciphertext.length);
        return output;
    }

    public boolean isHealthy() {
        return !shuttingDown && !drainComplete;
    }

    public int getActiveJobCount() {
        return activeJobs.get();
    }

    static class FileTask {
        final String id;
        final File file;
        final long startTime;
        volatile boolean complete = false;

        FileTask(String id, File file, long startTime) {
            this.id = id;
            this.file = file;
            this.startTime = startTime;
        }

        void markComplete() { this.complete = true; }
    }

    public static void main(String[] args) throws Exception {
        FileProcessingService service = new FileProcessingService(4);
        System.out.println("FileProcessingService started, monitoring " + UPLOAD_DIR);

        // Main loop: watch for new files from reverse proxy uploads
        WatchService watcher = FileSystems.getDefault().newWatchService();
        Path uploadPath = Paths.get(UPLOAD_DIR);
        uploadPath.register(watcher, StandardWatchEventKinds.ENTRY_CREATE);

        while (service.isHealthy()) {
            WatchKey key = watcher.poll(1, TimeUnit.SECONDS);
            if (key == null) continue;

            for (WatchEvent<?> event : key.pollEvents()) {
                if (event.kind() == StandardWatchEventKinds.ENTRY_CREATE) {
                    // Use only the file name component to prevent path traversal.
                    Path ctx = (Path) event.context();
                    Path nameOnly = ctx.getFileName();
                    if (nameOnly == null) continue;
                    Path filePath = uploadPath.resolve(nameOnly).normalize();
                    if (!filePath.startsWith(uploadPath.toAbsolutePath().normalize())) {
                        System.err.println("Rejected suspicious path: " + ctx);
                        continue;
                    }
                    String taskId = "task-" + System.nanoTime();
                    service.workerPool.submit(() -> {
                        try {
                            service.processFile(taskId, filePath.toFile());
                        } catch (Exception e) {
                            System.err.println("Processing failed: " + e.getMessage());
                        }
                    });
                }
            }
            key.reset();
        }
    }
}
